/**
 * Inline brand mark for the Highcom Work client plugin.
 *
 * The Client bundle pipeline compiles CSS but carries no raster asset loader, so
 * the mark travels as a data URI inside lib/client.js instead of as a sibling
 * file nothing would serve. Generated from apps/desktop/build-highcom/icon.png
 * (256x256 RGBA PNG), the artwork's single source of truth; regenerate by
 * base64-encoding that file into the constant below.
 */

/** 256x256 RGBA PNG data URI for the Highcom Work mark. */
export const BRAND_MARK_DATA_URI =
  'data:image/png;base64,'
